#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin>>n;
    vector<int> ks(n);
    vector<vector<pair<int,int>>> cells(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>ks[i]; cells[i].resize(ks[i]);
        for(int j=0;j<ks[i];j++) cin>>cells[i][j].first>>cells[i][j].second;
        totalCells+=ks[i];
    }

    auto applyTransform=[](const vector<pair<int,int>>& src, int f, int r)->vector<pair<int,int>>{
        vector<pair<int,int>> res;
        for(auto [x,y]:src){
            int nx=x,ny=y;
            if(f) nx=-nx;
            for(int q=0;q<r;q++){int t=nx;nx=-ny;ny=t;}
            res.push_back({nx,ny});
        }
        int mx=INT_MAX,my=INT_MAX;
        for(auto&[x,y]:res){mx=min(mx,x);my=min(my,y);}
        for(auto&[x,y]:res){x-=mx;y-=my;}
        return res;
    };

    struct Ori{vector<pair<int,int>> c;int w,h,f,r;};
    vector<vector<Ori>> oris(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++) for(int r=0;r<4;r++){
            auto tc=applyTransform(cells[i],f,r);
            sort(tc.begin(),tc.end());
            if(seen.insert(tc).second){
                int w=0,h=0;
                for(auto[x,y]:tc){w=max(w,x+1);h=max(h,y+1);}
                oris[i].push_back({tc,w,h,f,r});
            }
        }
    }

    vector<int> order(n); iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return ks[a]>ks[b];});

    auto t0=chrono::steady_clock::now();
    auto el=[&]{return chrono::duration<double>(chrono::steady_clock::now()-t0).count();};

    int S=max(1,(int)ceil(sqrt((double)totalCells)));
    long long bestArea=1LL<<60; int bestW=0,bestH=0;
    struct Pl{int x,y,r,f;};
    vector<Pl> bestPl(n);

    for(int W=max(1,S/3);W<=totalCells*2&&el()<8.5;W++){
        int MH=totalCells/max(1,W-1)+200;
        vector<int> hmap(W,0);
        vector<vector<bool>> grid(W,vector<bool>(MH,false));
        vector<Pl> pl(n); int curH=0; bool fail=false;
        for(int idx=0;idx<n&&!fail;idx++){
            int pi=order[idx]; int bs=INT_MAX,bx=-1,by=-1,bo=-1;
            for(int oi=0;oi<(int)oris[pi].size();oi++){
                auto&o=oris[pi][oi]; if(o.w>W)continue;
                for(int x=0;x<=W-o.w;x++){
                    int my=0; for(auto[cx,cy]:o.c) my=max(my,hmap[x+cx]-cy);
                    if(my<0)my=0;
                    int top=0; for(auto[cx,cy]:o.c) top=max(top,my+cy+1);
                    if(top>MH)continue;
                    bool ok=true;
                    for(auto[cx,cy]:o.c) if(grid[x+cx][my+cy]){ok=false;break;}
                    if(ok){int sc=top*10000+x; if(sc<bs){bs=sc;bx=x;by=my;bo=oi;}}
                }
            }
            if(bx<0){fail=true;break;}
            auto&o=oris[pi][bo];
            for(auto[cx,cy]:o.c){grid[bx+cx][by+cy]=true;hmap[bx+cx]=max(hmap[bx+cx],by+cy+1);curH=max(curH,by+cy+1);}
            pl[pi]={bx,by,o.r,o.f};
        }
        if(fail)continue;
        long long area=(long long)W*curH;
        if(area<bestArea){bestArea=area;bestW=W;bestH=curH;bestPl=pl;}
        if(bestArea<=totalCells)break;
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
}
